"use client";

import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import type { PanInfo } from "motion/react";
import { useState } from "react";
import type { ComponentProps, ReactNode } from "react";

export type SwipeToDismissPrimitiveProps = Omit<ComponentProps<typeof motion.div>, "children" | "onDragEnd"> & {
  children: ReactNode;
  onDismiss?: () => void;
  threshold?: number;
};

export function SwipeToDismissPrimitive({ children, onDismiss, threshold = 96, ...props }: SwipeToDismissPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  const [visible, setVisible] = useState(true);
  const x = useMotionValue(0);
  const opacity = useTransform(x, [-threshold, 0, threshold], [0, 1, 0]);

  async function finishDrag(_: MouseEvent | TouchEvent | PointerEvent, info: PanInfo) {
    const shouldDismiss = Math.abs(info.offset.x) >= threshold || Math.abs(info.velocity.x) >= 800;
    if (!shouldDismiss) {
      await animate(x, 0, { type: "spring", stiffness: 360, damping: 30 });
      return;
    }
    const direction = info.offset.x === 0 ? Math.sign(info.velocity.x) || 1 : Math.sign(info.offset.x);
    await animate(x, direction * (threshold + 160), { duration: reduceMotion ? 0.12 : 0.24, ease: [0.16, 1, 0.3, 1] });
    setVisible(false);
    onDismiss?.();
  }

  return (
    <AnimatePresence initial={false}>
      {visible ? (
        <motion.div
          {...props}
          drag="x"
          dragConstraints={{ left: 0, right: 0 }}
          dragElastic={0.35}
          dragMomentum={false}
          onDragEnd={finishDrag}
          exit={{ opacity: 0 }}
          style={{ ...props.style, x, opacity }}
        >
          {children}
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}
